use crate::aap::caps::{http_client, state_read};

struct Node;

/// Key in the `subscriptions` store holding newline-separated feed URLs.
const SUBSCRIPTIONS_KEY: &str = "urls";

/// Enrichment endpoint granted to this node by the graph author.
const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything except RFC 3986 unreserved characters.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment side-call, granted via aap:caps/http-client. RunInfo has no
        // free-text field, so the only string input (`date`) is the query value.
        // A transport failure comes back as Err and is deliberately ignored: the
        // enrichment does not contribute to the output. Out-of-allowlist requests
        // trap at the boundary, as the interface defines.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
        let _ = http_client::fetch(&url);

        // Output is derived solely from the subscriptions store, so it is
        // unchanged by the enrichment call above.
        let urls: Vec<String> = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
